import{_ as o,l as D,o as r,c as n,v as e,p as i,x as t,d as m,i as s,S as p}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"最大回撤与 Calmar","description":"","frontmatter":{"title":"最大回撤与 Calmar","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/drawdown-calmar.md","filePath":"quant/drawdown-calmar.md","lastUpdated":1789023840000}'),d={name:"quant/drawdown-calmar.md"};function h(M,a,C,E,u,c){const l=D("Mermaid");return r(),n("div",null,[a[1]||(a[1]=e('<h1 id="最大回撤与-calmar" tabindex="-1">最大回撤与 Calmar <a class="header-anchor" href="#最大回撤与-calmar" aria-label="Permalink to &quot;最大回撤与 Calmar&quot;">​</a></h1><div class="epigraph"><p>Calmar 比率用年化收益除以最大回撤，把路径上最深的那一次亏损放到分母里；它比夏普更贴近期货账户「还能不能活下去」的问题，而不是把盈亏当成对称波动。</p><footer>—— Young, Calmar Ratio: A Smoother Tool, Futures, 1991</footer></div><p><a href="/quant/ir-sharpe">Sharpe 与 IR</a> 用标准差度量风险，对路径不敏感：同样的月收益集合，排列顺序可以改变账户是否爆仓，却几乎不改变夏普。最大回撤（maximum drawdown, MDD）记录净值从历史峰值落到谷底的最深比例，是路径统计量。Calmar 比率把年化复合收益放在分子、MDD 的绝对值放在分母，Young（1991）把它作为管理期货账户的平滑评价工具，窗口常取三十六个月。本篇写 MDD 的定义、抽样性质、与 Calmar / Sterling 一类回撤比的用法，以及它在组合约束里能做什么、不能做什么。它不是一个保证较低亏损的优化目标——把历史 MDD 最小化，往往会拟合那一条已经看见的路径。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>记净值 \\(V_t\\)，峰值 \\(M_t=\\max_{s\\le t}V_s\\)，回撤 \\(D_t=(M_t-V_t)/M_t\\)（或对数差）。最大回撤 \\(\\mathrm{MDD}=\\max_t D_t\\)。投资人关心的问题是：从任意一个高点出发，策略曾经让财富跌掉多少，以及用了多久才恢复（若恢复了）。方差把一次 −40% 和一串 ±2% 的 squiggle 按二阶混在一起；MDD 把前者单独标出来。杠杆、再平衡与赎回规则都对 MDD 敏感：同样的算术夏普，杠杆翻倍时 MDD 往往远不止翻倍，因为跌深之后的复合与强制去杠杆会叠加。</p><p>Calmar 试图用一个比把「赚得多不多」和「跌得深不深」压缩在一起：</p> \\[\\mathrm{Calmar}=\\frac{\\text{年化复合收益}}{|\\mathrm{MDD}|}. \\]<p>问题立刻变成窗口与样本：三十六个月里没碰到策略的特征左尾，Calmar 会虚高；窗口刚好覆盖 2008 或 2015，又会把一个十年策略钉死在一次宏观事件上。它比较的是<strong>该窗口内的路径效率</strong>，不是期望 Calmar。</p><h3 id="回撤是路径对象-有持续时间" tabindex="-1">回撤是路径对象，有持续时间 <a class="header-anchor" href="#回撤是路径对象-有持续时间" aria-label="Permalink to &quot;回撤是路径对象，有持续时间&quot;">​</a></h3><p>MDD 只是深度。平均回撤、水下时间、恢复时间、回撤面积（净值在峰值下方的积分）描述另一半。Chekhlov、Uryasev 与 Zabarankin（2005）把回撤过程放进优化，定义条件回撤风险（CDaR）一类可计算的风险测度。工程上至少应同时报告：MDD、发生区间、恢复是否完成、以及同窗口的 Sharpe。只有 Calmar 的排行榜会偏好「没经历过压力、收益尚可」的短样本。</p><p><span class="marginnote">Magdon-Ismail 等人给出布朗运动最大回撤的期望与分布近似：MDD 随 \\(\\sigma\\sqrt{T}\\) 增长，并依赖漂移。把一年样本的 MDD 当「风险预算」外推到十年，会系统性低估。漂移为正时 MDD 的期望仍随时间上升，只是上升得更慢——不是「正期望就不会有大回撤」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>计算必须在评价用的同一条净值上：同一费用、同一杠杆、同一再平衡。用毛收益序列算 MDD、用净收益算年化收益，Calmar 会假好。频率上，日净值比月净值更深：月采样会切掉月内峰值。管理期货传统用月数据，股票多空应用日数据，并声明。对数与简单比例在深回撤上差几个点，应固定一种。</p><p>窗口：Young 的实践是滚动三十六个月取 Calmar，再对滚动值平滑。评价一只基金应同时给：全样本 MDD（最坏已实现）、滚动 Calmar 的分位数、以及压力子样本。全样本最小回撤比在策略变更（加杠杆、换信号）后不可比，应分段。Sterling 比率用平均最大回撤（若干次深度回撤的均值）当除数，对单次极端稍不敏感；Burke 用回撤平方和。名字不同，都是回撤矩，都要声明窗口。</p><p>若把 MDD 或 CDaR 放进优化器，必须用样本外路径或情景，而不是把回测里那一次最大跌幅「优化掉」——那只会把权重从当时亏钱的资产上挪走，下一次危机换一个方向。情景应包括：波动升与相关升同时发生、融资加保证金、以及<a href="/quant/rebalance-rules">再平衡规则</a>在压力里强制交易。历史 MDD 是下界的一个观测，不是上界。</p><h3 id="与止损、杠杆的关系" tabindex="-1">与止损、杠杆的关系 <a class="header-anchor" href="#与止损、杠杆的关系" aria-label="Permalink to &quot;与止损、杠杆的关系&quot;">​</a></h3><p>账户止损、策略止损与 MDD 相关但不是同一对象。止损是交易规则，改变未来路径；MDD 是评价统计。回测里把止损设在「刚好避开历史 MDD」会制造不可重复的 Calmar，见 <a href="/quant/statarb-stops">统计套利止损</a> 对路径依赖的讨论。杠杆方面：无摩擦时收益与波动同乘，Sharpe 不变，MDD 近似同乘（在连续复合与无强平下仍只是近似），Calmar 对杠杆近似不变；有强平、有冲击时，高杠杆把 MDD 推过不可恢复的阈值，Calmar 崩溃。因此 Calmar 对杠杆的「不变性」比 Sharpe 更脆。</p><p><span class="marginnote">Calmar 的分子是复合收益，分母是一次极值。极值的抽样误差远大于均值与方差。三年样本上排 Calmar，实质上是在排「谁还没碰到自己的左尾」。这与用短窗 Sortino 排基金是同一类错误，只是分母更极端。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>净值是乘积过程。下跌时杠杆若不变，百分比回撤由收益序列的局部和决定；下跌时若因波动目标或保证金去杠杆，回撤会加深且恢复更慢——跌在高杠杆段、涨在低杠杆段。风险平价与波动目标在 2020 年一类月份的同步去杠杆，是这种机制的账户版。MDD 因此编码了规则与市场的相互作用，不只是「收益的左尾」。</p><p>布朗运动加漂移下，MDD 的期望随时间上升，说明「策略运行越久，越可能刷新 MDD」是扩散的性质，不是策略变坏。评价时应看单位时间的回撤增长是否异常，而不是要求十年 MDD 等于三年 MDD。正漂移减缓刷新速度，但不设上限。把 Calmar 当停止条件（低于某值就关策略）会在刚刷新 MDD 之后关掉——恰恰是分母最大、比率最差的时刻，可能是样本内最差的择时。</p><h3 id="calmar-不替代下行矩-更不替代压力测试" tabindex="-1">Calmar 不替代下行矩，更不替代压力测试 <a class="header-anchor" href="#calmar-不替代下行矩-更不替代压力测试" aria-label="Permalink to &quot;Calmar 不替代下行矩，更不替代压力测试&quot;">​</a></h3><p>Sortino 用所有低于 \\(T\\) 的观测；MDD 用一条路径上的一次最大深度。一个经常小亏的策略 Sortino 差、MDD 未必大；一个九年平稳、一年腰斩的策略 Sharpe 尚可、Calmar 很差。两者互补。<a href="/quant/evt">EVT</a> 试图对尾部分布建模，给出尚未看见的分位；MDD 只总结已经看见的路径。产品风控应同时有：已实现 MDD 限额、前瞻性压力（因子情景、流动性情景）、以及杠杆与换手约束。只用历史 Calmar 做限额，等于假设下一次危机不会更深。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>幸存者偏差：能被拿来展示 Calmar 的账户，往往已经过了一次选择——爆掉的路径不在库里。期货 CTA 排行榜尤其严重。恢复时间依赖后续收益，用「已恢复的回撤」做统计会丢掉仍在水下的账户。A 股涨跌停与停牌造成的净值跳跃，应与连续交易假设下的 MDD 分开标注。</p><p>不要声称优化 Calmar 能得到更安全的策略。目标非凸、高度路径依赖，样本内最优在样本外常翻转。不要把 Calmar 与 Sharpe 的差异解释成「技能质量」：差异主要来自非对称与单次极值。不要年化 MDD（不存在合法的 \\(\\sqrt{q}\\) 年化）；深度不按独立增量的平方根缩放，尤其在有漂移与杠杆规则时。</p><p>对个人账户与对基金，MDD 的含义还差一层：基金有赎回与门，深回撤会改变 AUM，从而改变冲击与杠杆，路径不再是外生收益的积分。评价基金 Calmar 时应尽量用当时真实杠杆与费用，而不是用恒定杠杆重放。</p><p><span class="marginnote">水下时间与恢复时间往往比 MDD 本身更能预测赎回。同样 −15% 的回撤，三个月回到峰值与三年仍在水下，对 Calmar 分子的后续复合完全不同。只报深度、不报持续时间，是半截路径统计。</span></p>',28)),(r(),i(p,null,{default:t(()=>[s(l,{id:"mermaid-80",class:"mermaid",graph:"flowchart%20TD%0A%20%20V%5B%22%E5%87%80%E5%80%BC%E8%B7%AF%E5%BE%84%20V_t%22%5D%20--%3E%20PK%5B%22%E5%B3%B0%E5%80%BC%20M_t%22%5D%0A%20%20V%20--%3E%20DD%5B%22%E5%9B%9E%E6%92%A4%E8%BF%87%E7%A8%8B%20D_t%22%5D%0A%20%20PK%20--%3E%20DD%0A%20%20DD%20--%3E%20MDD%5B%22%E6%9C%80%E5%A4%A7%E5%9B%9E%E6%92%A4%20MDD%22%5D%0A%20%20RET%5B%22%E5%B9%B4%E5%8C%96%E5%A4%8D%E5%90%88%E6%94%B6%E7%9B%8A%22%5D%20--%3E%20CAL%5B%22Calmar%20%3D%20%E6%94%B6%E7%9B%8A%20%2F%20%7CMDD%7C%22%5D%0A%20%20MDD%20--%3E%20CAL%0A%20%20CAL%20--%3E%20USE%5B%22%E7%AA%97%E5%8F%A3%E5%8C%96%E6%AF%94%E8%BE%83%E4%B8%8E%E9%99%90%E9%A2%9D%22%5D%0A%20%20MDD%20--%3E%20ST%5B%22%E5%8E%8B%E5%8A%9B%E6%83%85%E6%99%AF%3A%20%E6%9B%B4%E6%B7%B1%E8%B7%AF%E5%BE%84%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>最大回撤是净值相对峰值的最深跌幅，是路径统计量；Sharpe / IR 几乎不读取顺序。</li><li>Calmar（Young, 1991）用年化复合收益除以 MDD，窗口与采样频率必须声明；它是描述比，不是期望效率。</li><li>布朗运动下 MDD 期望随时间上升（Magdon-Ismail 等）；用短窗 MDD 当长期风险预算会低估。</li><li>杠杆、波动目标与强平使 Calmar 对杠杆比 Sharpe 更脆；止损规则会改变未来 MDD，不能按历史谷底标定。</li><li>回撤优化极易拟合已见路径；应配合 CDaR 或情景，而不是把回测 MDD 最小化。</li><li>出处：Young, <em>Calmar Ratio: A Smoother Tool</em>, Futures, 1991；Magdon-Ismail, Atiya, Pratap and Abu-Mostafa, <em>On the Maximum Drawdown of a Brownian Motion</em>, Journal of Applied Probability, 2004；Chekhlov, Uryasev and Zabarankin, <em>Drawdown Measure in Portfolio Optimization</em>, International Journal of Theoretical and Applied Finance, 2005。</li></ul>',2))])}const B=o(d,[["render",h]]);export{_ as __pageData,B as default};
